const fs=require('node:fs/promises'),os=require('node:os'),path=require('node:path'),http=require('node:http'),{execFile}=require('node:child_process'),{promisify}=require('node:util');
const run=promisify(execFile),root=path.resolve(__dirname,'../..');
(async()=>{const temporary=await fs.mkdtemp(path.join(os.tmpdir(),'nav-browser-engine-'));process.env.NAV_MEDIA_ADDONS_FILE=path.join(temporary,'addons.json');process.env.NAV_MEDIA_CACHE_DIR=path.join(temporary,'cache');process.env.NAV_TORRENT_LOCAL_ONLY='1';let app,addon,seeder;const files=path.join(temporary,'owned-fixture');await fs.mkdir(files);await run('ffmpeg',['-v','error','-f','lavfi','-i','testsrc2=size=320x180:rate=24','-f','lavfi','-i','sine=frequency=440:sample_rate=48000','-t','14','-c:v','ffv1','-c:a','pcm_s16le',path.join(files,'owned-film.mkv')]);await run('ffmpeg',['-v','error','-f','lavfi','-i','testsrc2=size=320x180:rate=24','-t','14','-c:v','libvpx','-b:v','150k',path.join(files,'owned-film.webm')]);const {default:WebTorrent}=await import('webtorrent');seeder=new WebTorrent({dht:false,tracker:false,lsd:false,utp:false,natUpnp:false,natPmp:false});seeder.on('error',console.error);const torrent=await new Promise(resolve=>seeder.seed(files,{announce:[],pieceLength:16384},resolve));const providers=require('../../media-providers');const client=await providers.mediaEngine.client();client.on('add',torrent=>{const connect=()=>torrent.addPeer('127.0.0.1:'+seeder.torrentPort);torrent.infoHash?connect():torrent.once('infoHash',connect)});
const manifest={id:'nav.owned-engine-fixture',name:'Local playback fixture',version:'1.0.0',types:['movie'],resources:['meta','stream'],catalogs:[],idPrefixes:['owned:']};const streams=[{name:'Torrent MKV',infoHash:torrent.infoHash,fileIdx:torrent.files.findIndex(f=>f.name==='owned-film.mkv')},{name:'Torrent WEBM',infoHash:torrent.infoHash,fileIdx:torrent.files.findIndex(f=>f.name==='owned-film.webm')},{name:'Choose torrent file',infoHash:torrent.infoHash},{name:'HTTP MKV',url:'http://127.0.0.1:33334/owned-film.mkv',behaviorHints:{notWebReady:true,filename:'owned-film.mkv',proxyHeaders:{request:{'X-Owned-Playback':'fixture'}}}}];
addon=http.createServer(async(req,res)=>{if(req.url==='/manifest.json'){res.setHeader('Content-Type','application/json');res.end(JSON.stringify(manifest));return}if(req.url.startsWith('/meta/')){res.setHeader('Content-Type','application/json');res.end(JSON.stringify({meta:{id:'owned:film',type:'movie',name:'Owned playback fixture'}}));return}if(req.url.startsWith('/stream/')){res.setHeader('Content-Type','application/json');res.end(JSON.stringify({streams}));return}if(req.url==='/owned-film.mkv'){if(req.headers['x-owned-playback']!=='fixture'){res.writeHead(403);res.end();return}const bytes=await fs.readFile(path.join(files,'owned-film.mkv')),range=/bytes=(\d+)-(\d*)/.exec(req.headers.range||''),start=range?Number(range[1]):0,end=range&&range[2]?Math.min(Number(range[2]),bytes.length-1):bytes.length-1;res.writeHead(range?206:200,{'Content-Type':'video/x-matroska','Content-Length':end-start+1,'Accept-Ranges':'bytes',...(range?{'Content-Range':`bytes ${start}-${end}/${bytes.length}`}:{})});res.end(req.method==='HEAD'?undefined:bytes.subarray(start,end+1));return}res.writeHead(404);res.end()});await new Promise(resolve=>addon.listen(33334,'127.0.0.1',resolve));
app=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');if(await providers.handleMediaProviders(req,res,url))return;const target=path.join(root,url.pathname==='/'?'index.html':url.pathname);if(!target.startsWith(root+path.sep)){res.writeHead(403);res.end();return}try{const bytes=await fs.readFile(target);res.setHeader('Content-Type',({'.js':'application/javascript','.css':'text/css','.html':'text/html','.svg':'image/svg+xml'})[path.extname(target)]||'application/octet-stream');res.end(bytes)}catch{res.writeHead(404);res.end()}});await new Promise(resolve=>app.listen(3003,'127.0.0.1',resolve));
async function shutdown(){await providers.closeMediaEngine();await new Promise(resolve=>seeder.destroy(()=>resolve()));app.close();addon.close();await fs.rm(temporary,{recursive:true,force:true});process.exit(0)}for(const signal of ['SIGTERM','SIGINT'])process.once(signal,shutdown);console.log('Owned media browser fixture on 3003; add-on on 33334');
})().catch(error=>{console.error(error);process.exit(1)});
